eview-${value}`}><i/><span><i/><i/><i/></span></span><span className="theme-option-label"><Icon data={value==='"'light'?Sun:Moon} size={16}/>{value==='light'?'Светлая':'Тёмная'}{theme===value&&<Icon data={CircleCheck} size={16}/>}</span></Button>)}</div><p className=\"setting-hint\">Тема сохраняется автоматически.</p></section><section className=\"settings-card\"><Text as=\"h2\" variant=\"header-1\">Уведомления</Text><div className=\"setting-switch-row\"><div><b>Активность команды</b><p className=\"subtle\">Показывать индикатор новых событий</p></div><Switch checked={notifications} onUpdate={setNotifications} controlProps={{'aria-label':'Уведомления об активности команды'}}/></div></section></div></div></>;
  return <ThemeProvider theme={theme}><AsideHeader className=\"app-shell\" compact={compact} onChangeCompact={setCompact} hideCollapseButton headerDecoration={false} hideSectionDividers logo={{text:'контур',textSize:27,icon:Mark,iconSize:33,href:'#overview',className:'app-logo'}} aboveMenuContent={"'!compact?<div className="sidebar-intro"><Button view="outlined" size="xl" width="max" className="workspace-button" onClick={()=>navigate('"'settings')}><span className=\"workspace-monogram\">С</span><span>{profile.workspace}</span><Icon data={ChevronDown} size={13}/></Button><div className=\"nav-caption\">ПРОСТРАНСТВО</div></div>:undefined} menuItems={[{id:'overview',title:'Обзор',icon:House,current:page==='overview',onItemClick:()=>navigate('overview')},{id:'projects',title:'Проекты',icon:Folder,current:page==='projects',onItemClick:()=>navigate('projects')},{id:'settings',title:'Настройки',icon:Gear,current:page==='settings',onItemClick:()=>navigate('settings')}]} renderFooter={()=> <div className={"'`sidebar-footer ${compact?'"'is-compact':''}"'`}>{!compact&&<div className="sidebar-tip"><span className="tip-spark">✧</span><b>Хорошие идеи любят порядок</b><p>Дайте следующей идее<br/>свой собственный проект.</p><Button view="outlined" width="max" onClick={openCreate}>Начать с идеи <Icon data={Plus} size={14}/></Button></div>}<Button className="help-button" view="flat" onClick={()=>setDialog('"'help')}><Icon data={CircleQuestion} size={18}/>{"'!compact&&'"'Помощь и поддержка'}</Button><div className=\"sidebar-theme\">{"'!compact&&<><Icon data={theme==='"'light'?Sun:Moon} size={18}/><span>{theme==='light'?'Светлая тема':'Тёмная тема'}</span></>}<Switch checked={theme==='dark'} onUpdate={checked=>setTheme(checked?'dark':'light')} controlProps={{'aria-label':'Тёмная тема'}}/></div><div className=\"sidebar-profile\"><Avatar name=\"АК\"/>{"'!compact&&<><div><b>{profile.name}</b><span>Личное пространство</span></div><Button view="flat" size="s" aria-label="Настройки профиля" onClick={()=>navigate('"'settings')}><Icon data={ChevronDown} size={13}/></Button></>}</div></div>} renderContent={()=> <div className=\"content-shell\"><header className=\"topbar\"><div className=\"breadcrumb\"><span>Рабочее пространство</span><span className=\"breadcrumb-slash\">/</span><b>{pageNames[page]}</b></div><div className=\"topbar-actions\"><span className=\"today-date\">{new Date().toLocaleDateString('ru-RU',{day:'numeric',month:'long'})}</span><span className=\"topbar-separator\"/><Button view=\"flat\" aria-label={theme==='light'?'Включить тёмную тему':'Включить светлую тему'} onClick={()=>setTheme(theme==='light'?'dark':'light')}><Icon data={theme==='light'?Sun:Moon} size={19}/></Button><Button view=\"flat\" className=\"notification-button\" aria-label=\"Уведомления\" onClick={()=>setDialog('notifications')}><Icon data={Bell} size={19}/>{notifications&&<span className=\"notification-dot\"/>}</Button><Avatar name=\"АК\" small/></div></header><main className=\"main-content\" key={page}>{page==='overview'?overview:page==='projects'?projectsPage:settingsPage}<footer className=\"page-footer\"><span>Меньше суеты. Больше смысла.</span><span><span className=\"online-dot\"/> Ваше пространство в порядке</span></footer></main></div>}/>
