import {useEffect, useState, type FormEvent} from 'react';
import {AsideHeader} from '@gravity-ui/navigation';
import {Button, Icon, Modal, Select, Switch, Text, TextInput, ThemeProvider} from '@gravity-ui/uikit';
import {ArrowRight, ArrowUpRight, Bell, Check, ChevronDown, CircleCheck, CircleQuestion, Clock, Folder, Gear, House, LayoutCellsLarge, LayoutList, Magnifier, Moon, Plus, Sun, Xmark, Persons} from '@gravity-ui/icons';
import './styles.css';

type Page = 'overview' | 'projects' | 'settings';
type Project = {id: string; name: string; description: string; category: string; color: string; done: number; total: number; date: string; members: string[]; status: 'active' | 'done'};
const initialProjects: Project[] = [
  {id:'1', name:'Сайт студии', description:'Новое пространство для наших идей', category:'Веб-дизайн', color:'mint', done:8, total:12, date:'12 ноября', members:['АК','МС','ДВ'], status:'active'},
  {id:'2', name:'Айдентика бренда', description:'Характер, который запоминается', category:'Брендинг', color:'lavender', done:5, total:8, date:'18 ноября', members:['МС','ЕЛ'], status:'active'},
  {id:'3', name:'Мобильное приложение', description:'Простые решения на каждый день', category:'Продукт', color:'peach', done:3, total:10, date:'24 ноября', members:['АК','ДВ','ЕЛ'], status:'active'},
  {id:'4', name:'Дизайн-система', description:'Общий язык наших продуктов', category:'Продукт', color:'mint', done:6, total:14, date:'28 ноября', members:['АК','МС'], status:'active'},
  {id:'5', name:'Осенняя кампания', description:'Новый сезон — новые возможности', category:'Маркетинг', color:'peach', done:12, total:12, date:'30 октября', members:['ЕЛ','ДВ'], status:'done'},
  {id:'6', name:'Портфолио команды', description:'Собрали то, чем гордимся', category:'Веб-дизайн', color:'lavender', done:8, total:8, date:'28 октября', members:['АК','МС','ЕЛ'], status:'done'},
];
const pageNames: Record<Page,string> = {overview:'Обзор',projects:'Проекты',settings:'Настройки'};
function readStored<T>(key: string, fallback: T): T {try {const value=localStorage.getItem(key); return value ? JSON.parse(value) : fallback;} catch {return fallback;}}
function useStored<T>(key: string, fallback: T) {
  const [value, setValue] = useState<T>(()=>readStored(key,fallback));
  useEffect(()=>{try {localStorage.setItem(key,JSON.stringify(value));} catch {/* In private mode, keep changes in memory. */}},[key,value]);
  return [value,setValue] as const;
}
function currentPage(): Page {const hash=window.location.hash.slice(1);return hash==='projects'||hash==='settings'?hash:'overview';}
function Mark(){return <span className=\"brand-mark\" aria-hidden=\"true\"><i/><i/><i/></span>;}
function Avatar({name, small=false}: {name:string;small?:boolean}) {return <span className={"'`avatar avatar-${name==='"'АК'?'green':name==='МС'?'purple':name==='ДВ'?'sand':'pink'} "'${small?'"'avatar-small':''}"'`} title={{'"'АК':'Алексей Ким','МС':'Мария Смирнова','ДВ':'Дмитрий Волков','ЕЛ':'Елена Лебедева'}[name] || name}>{name}</span>;}
function ProjectArt({color}: {color:string}) {return <div className={"'`project-art ${color}`} aria-hidden="true">{color==='"'mint'?<div className=\"art-squares\"><i/><i/><i/></div>:color==='lavender'?<div className=\"art-type\">Aa<span>ФОРМА И СМЫСЛ</span></div>:<div className=\"art-shapes\"><i/><i/><i/><i/></div>}<span className=\"art-dots\">•••</span></div>;}
function Activity(){return <div className=\"activity-list\">{[
  {name:'МС',text:<><b>Мария</b> завершила задачу <strong>«Главный экран»</strong></>,project:'Сайт студии',time:'15 минут назад'},
  {name:'ДВ',text:<><b>Дмитрий</b> добавил новые материалы</>,project:'Мобильное приложение',time:'1 час назад'},
  {name:'ЕЛ',text:<><b>Елена</b> обновила палитру бренда</>,project:'Айдентика бренда',time:'2 часа назад'},
].map((item,i)=><div className=\"activity-item\" key={i}><Avatar name={item.name}/><div className=\"activity-copy\"><div>{item.text}</div><span>{item.project}</span></div><span className=\"activity-time\">{item.time}</span></div>)}</div>;}

export function App() {
  const [theme,setTheme]=useStored<'light'|'dark'>('kontur-theme','light');
  const [projects,setProjects]=useStored<Project[]>('kontur-projects',initialProjects);
  const [profile,setProfile]=useStored('kontur-profile',{name:'Алексей',email:'alexey@studio.design',workspace:'Студия дизайна'});
  const [notifications,setNotifications]=useStored('kontur-notifications',true);
  const [page,setPage]=useState<Page>(currentPage);
  const [compact,setCompact]=useState(window.innerWidth<850);
  const [query,setQuery]=useState('');
  const [filter,setFilter]=useState('all');
  const [listView,setListView]=useState(false);
  const [dialog,setDialog]=useState<'create'|'notifications'|'help'|null>(null);
  const [selected,setSelected]=useState<Project|null>(null);
  const [projectName,setProjectName]=useState('');
  const [description,setDescription]=useState('');
  const [category,setCategory]=useState(['Веб-дизайн']);
  const [formError,setFormError]=useState('');
  const [toast,setToast]=useState('');
  const [draft,setDraft]=useState(profile);
  useEffect(()=>{const listener=()=>{setPage(currentPage());setQuery('');};window.addEventListener('hashchange',listener);return ()=>window.removeEventListener('hashchange',listener);},[]);
  useEffect(()=>{const listener=()=>setCompact(window.innerWidth<850);window.addEventListener('resize',listener);return ()=>window.removeEventListener('resize',listener);},[]);
  useEffect(()=>{if(toast){const timer=setTimeout(()=>setToast(''),3500);return ()=>clearTimeout(timer);}},[toast]);
