nClick={()=>navigate('"'settings')}><Icon data={ChevronDown} size={13}/></Button></>}</div></div>} renderContent={()=> <div className=\"content-shell\"><header className=\"topbar\"><div className=\"breadcrumb\"><span>Рабочее пространство</span><span className=\"breadcrumb-slash\">/</span><b>{pageNames[page]}</b></div><div className=\"topbar-actions\"><span className=\"today-date\">{new Date().toLocaleDateString('ru-RU',{day:'numeric',month:'long'})}</span><span className=\"topbar-separator\"/><Button view=\"flat\" aria-label={theme==='light'?'Включить тёмную тему':'Включить светлую тему'} onClick={()=>setTheme(theme==='light'?'dark':'light')}><Icon data={theme==='light'?Sun:Moon} size={19}/></Button><Button view=\"flat\" className=\"notification-button\" aria-label=\"Уведомления\" onClick={()=>setDialog('notifications')}><Icon data={Bell} size={19}/>{notifications&&<span className=\"notification-dot\"/>}</Button><Avatar name=\"АК\" small/></div></header><main className=\"main-content\" key={page}>{page==='overview'?overview:page==='projects'?projectsPage:settingsPage}<footer className=\"page-footer\"><span>Меньше суеты. Больше смысла.</span><span><span className=\"online-dot\"/> Ваше пространство в порядке</span></footer></main></div>}/>
