flex-start;margin-top:var(--g-spacing-6)}.filter-tabs{gap:var(--g-spacing-1)}.filter-tabs .g-button{font-size:10px}.view-buttons{display:none}.list-view .project-card{display:block}.list-view .project-art-wrap{width:auto}.settings-grid{margin-top:var(--g-spacing-5)}.project-search{max-width:100%}.toast{width:max-content}.dialog-content{padding:var(--g-spacing-5)}}
