item.command:
/bin/bash -lc "cat > src/styles.css <<'EOF'
.g-root {
  --g-font-family-sans: 'Inter', 'Arial', sans-serif;
  --g-border-radius-xs: 4px;
  --g-border-radius-s: 6px;
  --g-border-radius-m: 8px;
  --g-border-radius-l: 12px;
  --g-border-radius-xl: 16px;
  --g-button-border-radius: var(--g-border-radius-m);
  --g-text-display-2-font-size: 32px;
  --g-text-display-2-line-height: 42px;
  --g-text-display-1-font-size: 29px;
  --g-text-display-1-line-height: 37px;
  --g-text-header-1-font-size: 18px;
  --g-text-header-1-line-height: 26px;
}
.g-root_theme_light {
  --g-color-base-background: #ffffff;
  --g-color-base-brand: #38735b;
  --g-color-base-brand-hover: #2c604b;
  --g-color-base-selection: #e7efe8;
  --g-color-base-selection-hover: #dce9df;
  --g-color-line-brand: #38735b;
  --g-color-line-focus: #38735b;
  --g-color-text-brand: #367057;
  --g-color-text-brand-heavy: #29583f;
  --g-color-text-brand-contrast: #ffffff;
  --g-color-text-link: #367057;
  --g-color-text-link-hover: #25543f;
  --g-color-text-link-visited: #367057;
  --g-color-text-link-visited-hover: #25543f;
  --g-color-text-primary: #282f2a;
  --g-color-text-secondary: #858982;
  --g-color-text-hint: #9b9f99;
  --g-color-line-generic: #e9ebe6;
  --g-color-base-generic: #f1f3ef;
  --g-color-base-generic-hover: #e9ede7;
  --g-color-app-canvas: #fbfcf9;
  --g-color-app-sidebar: #f6f8f3;
  --g-color-app-hero: #eaf0e5;
  --g-color-app-hero-ink: #354f3a;
  --g-color-app-hero-line: #c9d7c2;
  --g-color-app-mint: #e8eee5;
  --g-color-app-mint-ink: #73937e;
  --g-color-app-lavender: #eeebf6;
  --g-color-app-lavender-ink: #8c77aa;
  --g-color-app-peach: #f7ece1;
  --g-color-app-peach-ink: #c48c69;
  --g-color-app-pink: #f0e3e2;
  --g-color-app-pink-ink: #a77a76;
  --g-color-app-note: #ffffff;
  --g-color-app-note-ink: #54755a;
  --g-color-app-note-back: #c9d7bc;
  --g-color-app-preview-light: #fafbf8;
  --g-color-app-preview-dark: #2c332e;
}
.g-root_theme_dark {
  --g-color-base-background: #222923;
  --g-color-base-brand: #85b397;
  --g-color-base-brand-hover: #a0c8ae;
  --g-color-base-selection: #334b3c;
  --g-color-base-selection-hover: #3c5745;
  --g-color-line-brand: #85b397;
  --g-color-line-focus: #85b397;
  --g-color-text-brand: #9ac4a6;
  --g-color-text-brand-heavy: #b3d3bc;
  --g-color-text-brand-contrast: #182b1f;
  --g-color-text-link: #9ac4a6;
  --g-color-text-link-hover: #c2e2cc;
  --g-color-text-link-visited: #9ac4a6;
  --g-color-text-link-visited-hover: #c2e2cc;
  --g-color-text-primary: #e5eae3;
  --g-color-text-secondary: #a0aaa0;
  --g-color-text-hint: #838f83;
  --g-color-line-generic: #363e36;
  --g-color-base-generic: #303830;
  --g-color-base-generic-hover: #3b453c;
  --g-color-app-canvas: #1d231e;
  --g-color-app-sidebar: #242c24;
  --g-color-app-hero: #303e2f;
  --g-color-app-hero-ink: #d2e0ca;
  --g-color-app-hero-line: #52634a;
  --g-color-app-mint: #344637;
  --g-color-app-mint-ink: #91b29a;
  --g-color-app-lavender: #3d354b;
  --g-color-app-lavender-ink: #bca3d6;
  --g-color-app-peach: #493c31;
  --g-color-app-peach-ink: #d7aa89;
  --g-color-app-pink: #49383b;
  --g-color-app-pink-ink: #d2a0a8;
  --g-color-app-note: #e1e7dc;
  --g-color-app-note-ink: #44674d;
  --g-color-app-note-back: #708363;
  --g-color-app-preview-light: #fafbf8;
  --g-color-app-preview-dark: #2c332e;
}
* {box-sizing: border-box;}
body {margin: 0; -webkit-font-smoothing: antialiased;}
body, .app-shell {background: var(--g-color-app-canvas);}
button, a, input { -webkit-tap-highlight-color: transparent; }
.app-shell {
  --gn-aside-header-background-color: var(--g-color-app-sidebar);
  --gn-aside-header-item-current-background-color: var(--g-color-base-selection);
  --gn-aside-header-item-current-icon-color: var(--g-color-text-brand);
  --gn-aside-header-item-current-text-color: var(--g-color-text-brand-heavy);
  --gn-aside-header-item-current-background-color-hover: var(--g-color-base-selection-hover);
  --gn-aside-header-item-text-color: var(--g-color-text-secondary);
  --gn-aside-header-item-icon-color: var(--g-color-text-secondary);
  --gn-aside-header-item-expanded-radius: var(--g-border-radius-m);
  --gn-aside-header-padding-top: var(--g-spacing-3);
}
.app-logo {font-weight: 720; letter-spacing: -1.2px;}
.brand-mark {position: relative; display: inline-flex; width: 31px; height: 31px; align-items: center; justify-content: center; gap: 3px; transform: rotate(-10deg);}
.brand-mark i {width: 7px; height: 26px; border-radius: var(--g-border-radius-xs); background: var(--g-color-text-brand); transform: skewY(-23deg);}
.brand-mark i:nth-child(2) {height: 31px;}
.brand-mark i:nth-child(3) {height: 22px;}
.sidebar-intro {padding: var(--g-spacing-5) var(--g-spacing-4) var(--g-spacing-2);}
.workspace-button {--g-button-border-color: var(--g-color-line-generic); --g-button-background-color:var(--g-color-base-background);--g-button-text-color:var(--g-color-text-primary);font-size: 12px;}
.workspace-monogram {display:inline-grid;place-items:center;width:24px;height:24px;background:var(--g-color-base-generic);border-radius:var(--g-border-radius-s);font-size:12px;font-weight:600;margin-right:var(--g-spacing-1);}
.nav-caption {font-size: 9px; letter-spacing: 1.4px; color:var(--g-color-text-hint); margin:var(--g-spacing-8) var(--g-spacing-2) var(--g-spacing-2);font-weight:600;}
.sidebar-footer {padding:var(--g-spacing-2) var(--g-spacing-2) 0;}
.sidebar-tip {background:var(--g-color-app-hero); border:1px solid var(--g-color-line-generic);border-radius:var(--g-border-radius-l);padding:var(--g-spacing-4);margin-bottom:var(--g-spacing-6);}
.tip-spark {font-size:29px;color:var(--g-color-text-brand);display:block;line-height:32px;margin-bottom:var(--g-spacing-3);}
.sidebar-tip b {font-size:12px;line-height:19px;display:block;font-weight:550;}
.sidebar-tip p {color:var(--g-color-text-secondary);font-size:11px;line-height:18px;margin:var(--g-spacing-2) 0 var(--g-spacing-4);}
.sidebar-tip .g-button {font-size:11px;--g-button-border-color:var(--g-color-app-hero-line);}
.help-button {--g-button-text-color:var(--g-color-text-secondary);font-size:12px;}
.sidebar-theme {display:flex;align-items:center;gap:var(--g-spacing-3);color:var(--g-color-text-secondary);font-size:12px;padding:var(--g-spacing-5) var(--g-spacing-2);}
.sidebar-theme span {flex:1;min-width:0;}
.sidebar-profile {display:flex;align-items:center;gap:var(--g-spacing-3);border-top:1px solid var(--g-color-line-generic);padding:var(--g-spacing-5) 0 var(--g-spacing-3);}
.sidebar-profile>div {min-width:0;flex:1;}
.sidebar-profile b {font-size:12px;font-weight:550;display:block;}
.sidebar-profile div>span {font-size:10px;display:block;color:var(--g-color-text-secondary);margin-top:var(--g-spacing-1);}
.is-compact {padding:0;}
.is-compact .sidebar-theme,.is-compact .sidebar-profile {justify-content:center;padding:var(--g-spacing-4) 0;}
.is-compact .help-button {width:100%;}
.topbar {height:76px;padding:0 var(--g-spacing-9);border-bottom:1px solid var(--g-color-line-generic);background:var(--g-color-base-background);display:flex;align-items:center;justify-content:space-between;gap:var(--g-spacing-4);}
.breadcrumb {display:flex;align-items:center;gap:var(--g-spacing-4);font-size:11px;}
.breadcrumb>span {color:var(--g-color-text-secondary);}
.breadcrumb b {font-weight:500;}
.breadcrumb-slash {opacity:.55;}
.topbar-actions {display:flex;align-items:center;gap:var(--g-spacing-3);flex-shrink:0;}
.today-date {color:var(--g-color-text-secondary);font-size:11px;}
.topbar-separator {height:18px;width:1px;background:var(--g-color-line-generic);margin:0 var(--g-spacing-2);}
.topbar-actions .g-button {--g-button-text-color:var(--g-color-text-secondary);}
.notification-button {position:relative;}
.notification-dot {position:absolute;right:8px;top:5px;width:5px;height:5px;background:var(--g-color-base-brand);border:1px solid var(--g-color-base-background);border-radius:50%;}
.content-shell {background:var(--g-color-app-canvas);min-height:100vh;}
.main-content {padding:var(--g-spacing-9) var(--g-spacing-9) 0;max-width:1500px;margin:0 auto;animation:appear .3s ease;}
.page-heading {display:flex;align-items:center;justify-content:space-between;gap:var(--g-spacing-5);margin-bottom:var(--g-spacing-7);}
.eyebrow {font-size:9px;letter-spacing:1.55px;color:var(--g-color-text-secondary);font-weight:550;margin-bottom:var(--g-spacing-2);}
h1,h2,p {margin:0;}
h1 {letter-spacing:-1.15px;font-weight:600"'!important;}
.heading-dot {color:var(--g-color-text-brand);}
.page-heading p {font-size:12px;color:var(--g-color-text-secondary);margin-top:var(--g-spacing-2);}
.page-heading>.g-button {flex-shrink:0;font-size:12px;}
.welcome-banner {position:relative;overflow:hidden;min-height:242px;background:var(--g-color-app-hero);border:1px solid var(--g-color-line-generic);border-radius:var(--g-border-radius-l);display:flex;align-items:center;justify-content:space-between;}
.welcome-content {padding:var(--g-spacing-7) var(--g-spacing-8);position:relative;z-index:2;}
.welcome-label {font-size:8px;letter-spacing:1.55px;color:var(--g-color-app-hero-ink);display:flex;align-items:center;gap:var(--g-spacing-2);font-weight:600;margin-bottom:var(--g-spacing-3);}
.small-spark {font-size:18px;}
.welcome-content h2 {font-weight:500;letter-spacing:-.65px;color:var(--g-color-app-hero-ink);}
.welcome-content p {color:var(--g-color-app-hero-ink);opacity:.65;font-size:11px;line-height:18px;margin-top:var(--g-spacing-3);}
.welcome-link {--g-button-text-color:var(--g-color-app-hero-ink);font-weight:550;font-size:11px;margin-top:var(--g-spacing-3);margin-left:calc(-1 * var(--g-spacing-3));}
.hero-art {position:absolute;right:4%;width:365px;height:280px;top:0;}
.orbit {position:absolute;border:1px solid var(--g-color-app-hero-line);border-radius:50%;transform:rotate(-35deg);}
.orbit-one {width:345px;height:185px;left:0;top:45px;}
.orbit-two {width:400px;height:235px;left:-25px;top:20px;}
.orbit-three {width:455px;height:285px;left:-50px;top:-5px;}
.floating-note {position:absolute;top:72px;left:107px;width:174px;height:142px;border-radius:var(--g-border-radius-l);}
.note-back {transform:rotate(-15deg);background:var(--g-color-app-note-back);top:50px;left:90px;padding:var(--g-spacing-6);}
.note-back>span {display:block;width:100%;height:5px;background:var(--g-color-app-note);opacity:.4;margin-bottom:var(--g-spacing-3);border-radius:var(--g-border-radius-s);}
.note-back>span:last-child {width:65%;}
.note-front {background:var(--g-color-app-note);transform:rotate(9deg);box-shadow:0 10px 24px var(--g-color-sfx-shadow);padding:var(--g-spacing-5);}
.note-icon {display:grid;place-items:center;width:35px;height:35px;background:var(--g-color-app-note-back);color:var(--g-color-app-note-ink);border-radius:var(--g-border-radius-m);}
.note-lines {position:absolute;top:var(--g-spacing-7);left:var(--g-spacing-17,66px);right:var(--g-spacing-5);}
.note-lines>span {display:block;height:6px;background:var(--g-color-app-note-back);margin-bottom:var(--g-spacing-2);border-radius:var(--g-border-radius-s);}
.note-lines>span:last-child {width:66%;opacity:.6;}
.note-progress {display:block;margin-top:var(--g-spacing-5);height:5px;background:linear-gradient(to right,var(--g-color-app-note-ink) 70%,var(--g-color-app-note-back) 70%);border-radius:var(--g-border-radius-s);}
.note-bottom {display:flex;align-items:center;margin-top:var(--g-spacing-4);}
.note-bottom i {width:16px;height:16px;border-radius:50%;background:var(--g-color-app-note-back);border:2px solid var(--g-color-app-note);margin-right:calc(-1 * var(--g-spacing-1));}
.note-bottom i:nth-child(2) {background:var(--g-color-app-peach-ink);}
.note-bottom i:nth-child(3) {background:var(--g-color-app-lavender-ink);}
.note-bottom>span {color:var(--g-color-app-note-ink);font-size:7px;margin-left:auto;}
.hero-star {position:absolute;color:var(--g-color-app-hero-ink);}
.star-one {left:40px;top:74px;font-size:40px;transform:rotate(15deg);}
.star-two {right:12px;bottom:55px;font-size:35px;}
.hero-tiny-dot {width:8px;height:8px;background:var(--g-color-app-note-ink);border-radius:50%;position:absolute;top:36px;right:56px;}
.stats-grid {display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:var(--g-spacing-4);margin:var(--g-spacing-6) 0 var(--g-spacing-8);}
.stat-card {position:relative;border:1px solid var(--g-color-line-generic);background:var(--g-color-base-background);border-radius:var(--g-border-radius-l);padding:var(--g-spacing-5);}
.stat-icon {position:absolute;right:var(--g-spacing-5);top:var(--g-spacing-4);color:var(--g-color-text-secondary);}
.stat-title {font-size:11px;color:var(--g-color-text-secondary);display:block;padding-right:var(--g-spacing-6);}
.stat-bottom {display:flex;justify-content:space-between;align-items:flex-end;margin-top:var(--g-spacing-4);gap:var(--g-spacing-2);}
.stat-bottom>.g-text {font-weight:500;line-height:35px;}
.stat-note {font-size:9px;white-space:nowrap;color:var(--g-color-text-secondary);margin-bottom:var(--g-spacing-1);display:flex;align-items:center;gap:var(--g-spacing-1);}
.positive {color:var(--g-color-text-brand);}
.section-heading {display:flex;align-items:center;justify-content:space-between;gap:var(--g-spacing-3);margin-bottom:var(--g-spacing-4);}
.section-heading>div {display:flex;align-items:center;gap:var(--g-spacing-3);}
.section-heading h2 {font-weight:550;letter-spacing:-.3px;}
.section-heading>.g-button {font-size:11px;--g-button-text-color:var(--g-color-text-secondary);}
.count-label {border:1px solid var(--g-color-line-generic);border-radius:var(--g-border-radius-s);font-size:10px;padding:0 var(--g-spacing-2);color:var(--g-color-text-secondary);line-height:20px;}
.projects-grid {display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:var(--g-spacing-5);}
.project-card {overflow:hidden;border:1px solid var(--g-color-line-generic);border-radius:var(--g-border-radius-l);background:var(--g-color-base-background);transition:box-shadow .2s,transform .2s;min-width:0;}
.project-card:hover {box-shadow:0 5px 18px color-mix(in srgb,var(--g-color-sfx-shadow) 30%,transparent);transform:translateY(-2px);}
.project-art-wrap {position:relative;margin:var(--g-spacing-2) var(--g-spacing-2) 0;}
.project-art {height:128px;position:relative;display:grid;place-items:center;overflow:hidden;border-radius:var(--g-border-radius-m);}
.mint {background:var(--g-color-app-mint);color:var(--g-color-app-mint-ink);}
.lavender {background:var(--g-color-app-lavender);color:var(--g-color-app-lavender-ink);}
.peach {background:var(--g-color-app-peach);color:var(--g-color-app-peach-ink);}
.art-dots {position:absolute;bottom:var(--g-spacing-2);right:var(--g-spacing-3);letter-spacing:2px;font-size:9px;opacity:.55;}
.art-squares {position:relative;width:94px;height:84px;transform:rotate(-13deg);}
.art-squares i {display:block;position:absolute;width:65px;height:65px;border:1px solid currentColor;border-radius:var(--g-border-radius-s);background:color-mix(in srgb,var(--g-color-app-mint-ink) 12%,var(--g-color-app-mint));}
.art-squares i:first-child {top:0;left:0;opacity:.5;}
.art-squares i:nth-child(2) {top:10px;left:13px;opacity:.75;}
