  {name:'ЕЛ',text:<><b>Елена</b> обновила палитру бренда</>,project:'Айдентика бренда',time:'2 часа назад'},
].map((item,i)=><div className=\"activity-item\" key={i}><Avatar name={item.name}/><div className=\"activity-copy\"><div>{item.text}</div><span>{item.project}</span></div><span className=\"activity-time\">{item.time}</span></div>)}</div>;}

export function App() {
  const [theme,setTheme]=useStored<'light'|'dark'>('kontur-theme','light');
